create extension if not exists pgcrypto;
create table if not exists pool_settings(id boolean primary key default true check(id),minimum_points int not null default 500,ranking_share_percent numeric not null default 70,lottery_share_percent numeric not null default 30,ranking_winner_limit int not null default 100,lottery_winner_count int not null default 10,season_days int not null default 7,revenue_percentages jsonb not null default'{"season_pass":5,"egg":5,"pet":4,"hero":3,"fc_purchase":2,"event":0,"ad":0}',activity_points jsonb not null default'{"daily_login":10,"daily_mission":20,"weekly_mission":100,"boss_defeat":40,"pvp_win":25,"ad_watch":5,"season_pass_purchase":300,"egg_purchase":80,"hero_purchase":60,"pet_purchase":80}',ranking_percentages jsonb not null default'{"1":15,"2":10,"3":8,"4-10":3,"11-25":2,"26-50":1}',updated_at timestamptz not null default now());
insert into pool_settings(id)values(true)on conflict do nothing;
create table if not exists pool_balance(id uuid primary key default gen_random_uuid(),week_label text not null,starts_at timestamptz not null,ends_at timestamptz not null,balance_ton numeric not null default 0 check(balance_ton>=0),status text not null default'active'check(status in('active','distributing','distributed','cancelled')),distribution_key text unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists pool_one_active on pool_balance(status)where status='active';
insert into pool_balance(week_label,starts_at,ends_at)select'Temporada '||to_char(now(),'IYYY-IW'),date_trunc('week',now()),date_trunc('week',now())+interval'7 days'where not exists(select 1 from pool_balance where status='active');
create table if not exists pool_wallets(user_id uuid primary key references game_players(id)on delete cascade,wallet_address text not null,connected_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists pool_points(id uuid primary key default gen_random_uuid(),pool_id uuid not null references pool_balance(id)on delete cascade,user_id uuid not null references game_players(id)on delete cascade,activity_type text not null,points int not null check(points>0),source_id text not null,idempotency_key text unique not null,created_at timestamptz not null default now());
create index if not exists pool_points_rank on pool_points(pool_id,user_id);
create table if not exists pool_history(id uuid primary key default gen_random_uuid(),pool_id uuid unique not null references pool_balance(id),week_label text not null,amount_ton numeric not null,winner_count int not null,seed_hash text not null,distributed_at timestamptz not null default now());
create table if not exists pool_rewards(id uuid primary key default gen_random_uuid(),history_id uuid not null references pool_history(id),user_id uuid not null references game_players(id),reward_type text not null check(reward_type in('ranking','lottery')),position int,amount_ton numeric not null check(amount_ton>0),idempotency_key text unique not null,status text not null default'pending'check(status in('pending','processing','paid','failed')),tx_hash text unique,created_at timestamptz not null default now(),paid_at timestamptz);
create table if not exists pool_winners(id uuid primary key default gen_random_uuid(),history_id uuid not null references pool_history(id),user_id uuid not null references game_players(id),winner_type text not null check(winner_type in('ranking','lottery')),position int,points int not null,created_at timestamptz not null default now(),unique(history_id,user_id,winner_type));
create table if not exists pool_revenue(id uuid primary key default gen_random_uuid(),pool_id uuid not null references pool_balance(id),user_id uuid references game_players(id),source_type text not null,source_id text not null,base_amount_ton numeric not null check(base_amount_ton>0),percent numeric not null check(percent>=0 and percent<=100),amount_ton numeric not null check(amount_ton>=0),idempotency_key text unique not null,created_at timestamptz not null default now());
grant all on pool_settings,pool_balance,pool_wallets,pool_points,pool_history,pool_rewards,pool_winners,pool_revenue to service_role;
revoke all on pool_settings,pool_balance,pool_wallets,pool_points,pool_history,pool_rewards,pool_winners,pool_revenue from anon,authenticated;
alter table pool_settings enable row level security;alter table pool_balance enable row level security;alter table pool_wallets enable row level security;alter table pool_points enable row level security;alter table pool_history enable row level security;alter table pool_rewards enable row level security;alter table pool_winners enable row level security;alter table pool_revenue enable row level security;

create or replace function award_pool_points(p_user_id uuid,p_activity text,p_source_id text)returns void language plpgsql security definer set search_path=public as $$declare s pool_settings%rowtype;b uuid;pts int;k text;begin select*into s from pool_settings where id;select id into b from pool_balance where status='active'for update;pts:=coalesce((s.activity_points->>p_activity)::int,0);if pts<=0 or b is null then return;end if;k:='pool_points:'||b||':'||p_activity||':'||p_source_id||':'||p_user_id;insert into pool_points(pool_id,user_id,activity_type,points,source_id,idempotency_key)values(b,p_user_id,p_activity,pts,p_source_id,k)on conflict(idempotency_key)do nothing;end$$;

create or replace function pool_record_revenue(p_user_id uuid,p_source_type text,p_source_id text,p_amount_ton numeric)returns void language plpgsql security definer set search_path=public as $$declare s pool_settings%rowtype;b uuid;p numeric;a numeric;k text;begin if p_amount_ton<=0 then raise exception'INVALID_TON_AMOUNT';end if;select*into s from pool_settings where id;select id into b from pool_balance where status='active'for update;p:=coalesce((s.revenue_percentages->>p_source_type)::numeric,0);a:=round(p_amount_ton*p/100,9);k:='pool_revenue:'||p_source_type||':'||p_source_id;insert into pool_revenue(pool_id,user_id,source_type,source_id,base_amount_ton,percent,amount_ton,idempotency_key)values(b,p_user_id,p_source_type,p_source_id,p_amount_ton,p,a,k)on conflict(idempotency_key)do nothing;if found then update pool_balance set balance_ton=balance_ton+a,updated_at=now()where id=b;end if;end$$;

create or replace function get_community_pool_dashboard(p_telegram_id bigint)returns jsonb language plpgsql security definer set search_path=public as $$declare u game_players%rowtype;b pool_balance%rowtype;s pool_settings%rowtype;pts int;pos int;eligible boolean;participants int;begin select*into u from game_players where telegram_id=p_telegram_id;select*into b from pool_balance where status='active';select*into s from pool_settings where id;if u.id is null or b.id is null then raise exception'POOL_NOT_AVAILABLE';end if;select coalesce(sum(points),0)::int into pts from pool_points where pool_id=b.id and user_id=u.id;eligible:=pts>=s.minimum_points and not coalesce(u.pvp_banned,false)and u.created_at<=now()-interval'7 days'and exists(select 1 from player_heroes where user_id=u.id)and exists(select 1 from pool_wallets where user_id=u.id);with scores as(select user_id,sum(points)::int points from pool_points where pool_id=b.id group by user_id),valid as(select sc.*,row_number()over(order by points desc,user_id)position from scores sc join game_players gp on gp.id=sc.user_id where sc.points>=s.minimum_points and not gp.pvp_banned and gp.created_at<=now()-interval'7 days'and exists(select 1 from player_heroes h where h.user_id=sc.user_id)and exists(select 1 from pool_wallets w where w.user_id=sc.user_id))select count(*)::int,max(case when user_id=u.id then position::int end)into participants,pos from valid;return jsonb_build_object('season',jsonb_build_object('id',b.id,'weekLabel',b.week_label,'balanceTon',b.balance_ton,'startsAt',b.starts_at,'endsAt',b.ends_at,'status',b.status),'player',jsonb_build_object('points',pts,'position',pos,'eligible',eligible,'walletConnected',exists(select 1 from pool_wallets where user_id=u.id),'accountAgeDays',floor(extract(epoch from(now()-u.created_at))/86400),'hasHero',exists(select 1 from player_heroes where user_id=u.id)),'settings',jsonb_build_object('minimumPoints',s.minimum_points,'rankingSharePercent',s.ranking_share_percent,'lotterySharePercent',s.lottery_share_percent),'participantCount',participants,'ranking',(with scores as(select pp.user_id,sum(pp.points)::int points from pool_points pp where pp.pool_id=b.id group by pp.user_id),r as(select row_number()over(order by points desc,user_id)position,sc.*,gp.display_name,gp.avatar_url from scores sc join game_players gp on gp.id=sc.user_id where sc.points>=s.minimum_points and not gp.pvp_banned order by points desc limit 100)select coalesce(jsonb_agg(jsonb_build_object('position',position,'playerId',user_id,'name',coalesce(display_name,'Jogador'),'avatarUrl',avatar_url,'points',points,'eligible',true,'estimatedPrizeTon',0)order by position),'[]')from r),'history',(select coalesce(jsonb_agg(jsonb_build_object('id',h.id,'weekLabel',h.week_label,'amountTon',h.amount_ton,'winnerCount',h.winner_count,'playerRewardTon',coalesce((select sum(amount_ton)from pool_rewards where history_id=h.id and user_id=u.id),0),'distributedAt',h.distributed_at)order by h.distributed_at desc),'[]')from(select*from pool_history order by distributed_at desc limit 12)h));end$$;

create or replace function distribute_community_pool(p_force boolean default false)returns uuid language plpgsql security definer set search_path=public as $$declare b pool_balance%rowtype;s pool_settings%rowtype;h uuid;seed text;ranking_total numeric;lottery_total numeric;winner_count int;begin perform pg_advisory_xact_lock(hashtext('community_pool_distribution'));select*into b from pool_balance where status='active'for update;if b.id is null then raise exception'NO_ACTIVE_POOL';end if;if not p_force and b.ends_at>now()then raise exception'POOL_NOT_DUE';end if;update pool_balance set status='distributing',updated_at=now()where id=b.id;select*into s from pool_settings where id;seed:=encode(gen_random_bytes(32),'hex');insert into pool_history(pool_id,week_label,amount_ton,winner_count,seed_hash)values(b.id,b.week_label,b.balance_ton,0,encode(digest(seed,'sha256'),'hex'))returning id into h;ranking_total:=b.balance_ton*s.ranking_share_percent/100;lottery_total:=b.balance_ton*s.lottery_share_percent/100;with scores as(select pp.user_id,sum(pp.points)::int points from pool_points pp join game_players gp on gp.id=pp.user_id where pp.pool_id=b.id and not gp.pvp_banned and gp.created_at<=now()-interval'7 days'and exists(select 1 from player_heroes x where x.user_id=pp.user_id)and exists(select 1 from pool_wallets w where w.user_id=pp.user_id)group by pp.user_id having sum(pp.points)>=s.minimum_points),ranked as(select*,row_number()over(order by points desc,user_id)pos from scores),awards as(select*,case when pos=1 then .15 when pos=2 then .10 when pos=3 then .08 when pos between 4 and 10 then .03/7 when pos between 11 and 25 then .02/15 when pos between 26 and 50 then .01/25 when pos between 51 and 100 then .61/50 else 0 end share from ranked where pos<=least(100,s.ranking_winner_limit))insert into pool_rewards(history_id,user_id,reward_type,position,amount_ton,idempotency_key)select h,user_id,'ranking',pos,greatest(.000000001,round(ranking_total*share,9)),'pool_reward:'||h||':ranking:'||user_id from awards on conflict do nothing;with scores as(select pp.user_id,sum(pp.points)::int points from pool_points pp join game_players gp on gp.id=pp.user_id where pp.pool_id=b.id and not gp.pvp_banned and gp.created_at<=now()-interval'7 days'and exists(select 1 from player_heroes x where x.user_id=pp.user_id)and exists(select 1 from pool_wallets w where w.user_id=pp.user_id)group by pp.user_id having sum(pp.points)>=s.minimum_points),draw as(select*,row_number()over(order by(-ln(greatest(.000000001,(('x'||substr(encode(digest(seed||user_id::text,'sha256'),'hex'),1,15))::bit(60)::bigint)::numeric/1152921504606846976)))/points)pick from scores)insert into pool_rewards(history_id,user_id,reward_type,amount_ton,idempotency_key)select h,user_id,'lottery',round(lottery_total/greatest(1,least(s.lottery_winner_count,(select count(*)from scores))),9),'pool_reward:'||h||':lottery:'||user_id from draw where pick<=s.lottery_winner_count on conflict do nothing;insert into pool_winners(history_id,user_id,winner_type,position,points)select h,r.user_id,r.reward_type,r.position,coalesce((select sum(points)::int from pool_points where pool_id=b.id and user_id=r.user_id),0)from pool_rewards r where r.history_id=h on conflict do nothing;select count(distinct user_id)::int into winner_count from pool_rewards where history_id=h;update pool_history set winner_count=winner_count where id=h;update pool_balance set status='distributed',distribution_key='pool_distribution:'||b.id,updated_at=now()where id=b.id;insert into pool_balance(week_label,starts_at,ends_at)values('Temporada '||to_char(now(),'IYYY-IW'),now(),now()+make_interval(days=>s.season_days));return h;end$$;

create or replace function refresh_pool_history_winners()returns trigger language plpgsql set search_path=public as $$declare target uuid:=coalesce(new.history_id,old.history_id);begin update pool_history set winner_count=(select count(distinct user_id)::int from pool_rewards where history_id=target)where id=target;return coalesce(new,old);end$$;
drop trigger if exists pool_reward_refresh_history on pool_rewards;
create trigger pool_reward_refresh_history after insert or delete on pool_rewards for each row execute function refresh_pool_history_winners();

create or replace function pool_points_from_game_event()returns trigger language plpgsql security definer set search_path=public as $$begin if tg_table_name='pvp_battles'then perform award_pool_points(new.winner_id,'pvp_win',new.id::text);elsif tg_table_name='boss_reward_transactions'then perform award_pool_points(new.user_id,'boss_defeat',new.combat_id::text);elsif tg_table_name='daily_calendar_claims'then perform award_pool_points(new.user_id,'daily_login',new.calendar_cycle||':'||new.day);end if;return new;end$$;
drop trigger if exists pool_points_pvp on pvp_battles;
drop trigger if exists pool_points_boss on boss_reward_transactions;
drop trigger if exists pool_points_daily_login on daily_calendar_claims;
create trigger pool_points_pvp after insert on pvp_battles for each row execute function pool_points_from_game_event();
create trigger pool_points_boss after insert on boss_reward_transactions for each row execute function pool_points_from_game_event();
create trigger pool_points_daily_login after insert on daily_calendar_claims for each row execute function pool_points_from_game_event();

create or replace function admin_update_pool_settings(p_minimum int,p_ranking numeric,p_lottery numeric,p_winners int,p_days int,p_revenue jsonb,p_points jsonb,p_ranking_config jsonb)returns void language plpgsql security definer set search_path=public as $$begin if p_minimum<0 or p_ranking<0 or p_lottery<0 or p_ranking+p_lottery<>100 or p_winners<1 or p_days<1 or exists(select 1 from jsonb_each_text(p_revenue)where value::numeric<0 or value::numeric>100)or exists(select 1 from jsonb_each_text(p_points)where value::int<0)then raise exception'INVALID_POOL_SETTINGS';end if;update pool_settings set minimum_points=p_minimum,ranking_share_percent=p_ranking,lottery_share_percent=p_lottery,lottery_winner_count=p_winners,season_days=p_days,revenue_percentages=p_revenue,activity_points=p_points,ranking_percentages=p_ranking_config,updated_at=now()where id;end$$;

create or replace function admin_adjust_pool_balance(p_amount numeric,p_reason text)returns numeric language plpgsql security definer set search_path=public as $$declare result numeric;begin if p_amount=0 or nullif(trim(p_reason),'')is null then raise exception'INVALID_POOL_ADJUSTMENT';end if;update pool_balance set balance_ton=greatest(0,balance_ton+p_amount),updated_at=now()where status='active'returning balance_ton into result;if result is null then raise exception'NO_ACTIVE_POOL';end if;return result;end$$;

create or replace function admin_cancel_pool()returns void language plpgsql security definer set search_path=public as $$begin update pool_balance set status='cancelled',updated_at=now()where status='active';end$$;

revoke all on function award_pool_points(uuid,text,text),pool_record_revenue(uuid,text,text,numeric),get_community_pool_dashboard(bigint),distribute_community_pool(boolean),admin_update_pool_settings(int,numeric,numeric,int,int,jsonb,jsonb,jsonb),admin_adjust_pool_balance(numeric,text),admin_cancel_pool()from public,anon,authenticated;
grant execute on function award_pool_points(uuid,text,text),pool_record_revenue(uuid,text,text,numeric),get_community_pool_dashboard(bigint),distribute_community_pool(boolean),admin_update_pool_settings(int,numeric,numeric,int,int,jsonb,jsonb,jsonb),admin_adjust_pool_balance(numeric,text),admin_cancel_pool()to service_role;